<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Laravel AIWMWeb Demo</title><style>body{font:7.5px system-ui;max-width:1100px;margin:auto;padding:2rem;background:#f6f7fb;color:#172033}section{background:white;padding:1rem;margin:1rem 0;border-radius:10px}input,button,textarea{padding:.6rem;margin:.25rem}pre{white-space:pre-wrap;background:#101827;color:#d8e4ff;padding:1rem;min-height:8rem}.row{display:flex;flex-wrap:wrap;gap:.5rem}</style>    <!-- Google Fonts: Inter (Latin) and Tajawal (Arabic); typography 25% larger than previous baseline. -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&amp;family=Tajawal:wght@400;500;700;800;900&amp;display=swap">
    <style data-aiwm-global-typography>
        :root { font-size: 62.5%; --aiwm-google-font: 'Inter', 'Tajawal', sans-serif; --font-sans: var(--aiwm-google-font); }
        html:lang(ar) { --aiwm-google-font: 'Tajawal', 'Inter', sans-serif; }
        body, button, input, textarea, select, option { font-family: var(--aiwm-google-font) !important; }
        @media (min-width: 1140px) { main :is(.cards, .record-grid, .data-cards, .details-grid, .stats-grid, .summary-grid, .info-grid, .settings-grid), main dl:has(> div) { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; } }
        @media (min-width: 701px) and (max-width: 1139px) { main :is(.cards, .record-grid, .data-cards, .details-grid, .stats-grid, .summary-grid, .info-grid, .settings-grid), main dl:has(> div) { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; } }
        @media (max-width: 700px) { main :is(.cards, .record-grid, .data-cards, .details-grid, .stats-grid, .summary-grid, .info-grid, .settings-grid), main dl:has(> div) { display: grid; grid-template-columns: minmax(0, 1fr); gap: 10px; } }
            /* Three-column forms, plan cards and history records; full-width actions retained. */
        @media (min-width: 1140px) { main .grid, main form:has(> label ~ label ~ label), main section:has(> article ~ article), main section:has(> .record ~ .record) { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; } }
        @media (min-width: 701px) and (max-width: 1139px) { main .grid, main form:has(> label ~ label ~ label), main section:has(> article ~ article), main section:has(> .record ~ .record) { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; } }
        @media (max-width: 700px) { main .grid, main form:has(> label ~ label ~ label), main section:has(> article ~ article), main section:has(> .record ~ .record) { display: grid; grid-template-columns: minmax(0, 1fr); gap: 10px; } }
        main form:has(> label ~ label ~ label) > :not(label), main section:has(> article ~ article) > :not(article), main section:has(> .record ~ .record) > :not(.record) { grid-column: 1 / -1; }
        main :is(.grid, .cards, .record-grid) > * { min-width: 0; }
</style>
</head><body>
<h1>Laravel AIWMWeb — Demo Journey</h1><p>Tenant: <strong>{{ $tenant }}</strong>. Every action below calls a persisted tenant-scoped API.</p>
<section><h2>Site</h2><div class="row"><input id="name" placeholder="Site name"><input id="url" placeholder="https://wordpress.test"><button onclick="createSite()">Add site</button><button onclick="listSites()">List sites</button></div></section>
<section><h2>Connector and sync</h2><div class="row"><input id="site" placeholder="Site ID"><button onclick="pair()">Generate pairing</button><button onclick="verify()">Verify</button><button onclick="sync()">Sync</button><button onclick="content()">Content explorer</button></div></section>
<section><h2>SEO to evidence</h2><div class="row"><button onclick="audit()">Run audit</button><input id="audit" placeholder="Audit ID"><button onclick="findings()">Findings</button><input id="finding" placeholder="Finding ID"><button onclick="suggest()">AI suggestion</button><input id="approval" placeholder="Approval ID"><button onclick="approve()">Approve</button><button onclick="execute()">Execute</button><input id="execution" placeholder="Execution ID"><button onclick="receipt()">Evidence receipt</button></div></section>
<pre id="out">Ready.</pre><script>const base='/api/tenants/{{ $tenant }}'; const out=x=>document.querySelector('#out').textContent=JSON.stringify(x,null,2); async function call(path,method='GET',body){let r=await fetch(base+path,{method,headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:body?JSON.stringify(body):undefined});let x=await r.json().catch(()=>({status:r.status}));out(x);return x}function v(id){return document.querySelector('#'+id).value}async function createSite(){let x=await call('/sites','POST',{name:v('name'),url:v('url')});if(x.id)document.querySelector('#site').value=x.id}function listSites(){return call('/sites')}function pair(){return call('/sites/'+v('site')+'/pairing','POST')}function verify(){return call('/sites/'+v('site')+'/verify','POST')}function sync(){return call('/sites/'+v('site')+'/sync','POST')}function content(){return call('/sites/'+v('site')+'/content')}async function audit(){let x=await call('/sites/'+v('site')+'/audits','POST');if(x.id)document.querySelector('#audit').value=x.id}function findings(){return call('/audits/'+v('audit')+'/findings')}function suggest(){return call('/findings/'+v('finding')+'/suggestions','POST')}function approve(){return call('/approvals/'+v('approval'),'POST',{status:'APPROVED'})}async function execute(){let x=await call('/approvals/'+v('approval')+'/execute','POST');if(x.id)document.querySelector('#execution').value=x.id}function receipt(){return call('/executions/'+v('execution')+'/receipt')}</script></body></html>
